// Take the most recent briefing and trim it to call-length.
// Output: a single item with json.script (max ~150 words of speech).
const rows = $input.all().map((i) => i.json).filter((r) => r && r.briefing);
if (!rows.length) {
  return [{ json: { script: '' } }]; // empty → the voice node skips (no call)
}
rows.sort((a, b) => String(b.sent_at).localeCompare(String(a.sent_at)));
const brief = String(rows[0].briefing || '');

function section(label) {
  const start = brief.indexOf(label);
  if (start === -1) return '';
  const rest = brief.slice(start + label.length);
  const labels = ["TODAY'S TASKS", 'DONE YESTERDAY', 'AI ON DECK TODAY', 'WORLD NEWS', 'NEEDS OUR ATTENTION'];
  let end = rest.length;
  for (const l of labels) {
    if (l === label) continue;
    const i = rest.indexOf(l);
    if (i !== -1 && i < end) end = i;
  }
  return rest.slice(0, end).trim();
}

const tasks = section("TODAY'S TASKS").split('\n').filter((l) => l.trim().startsWith('-')).slice(0, 3);
const attn = section('NEEDS OUR ATTENTION').split('\n').filter((l) => l.trim().startsWith('-')).slice(0, 2);

const clean = (arr) => arr.map((l) => l.replace(/^-\s*/, '').trim());

let script = 'Good morning, Miss Akiru. This is an automated call from your own systems, Akiru Systems. Two-minute brief.\n\n';
script += tasks.length ? 'Today\'s tasks: ' + clean(tasks).join('; ') + '.' : 'No tasks logged for today.';
script += '\n\n';
script += attn.length ? 'Needs attention: ' + clean(attn).join('; ') + '.' : 'Nothing beyond the log.';
script += '\n\nThat\'s the picture. The full brief is in your inbox. Have a good day.';

return [{ json: { script, briefing_date: rows[0].sent_at } }];
